import React from 'react';

function WhyUsSection() {
    return (
        <div className="whyUsSection w-full h-96 bg-red-200 flex justify-center items-center">
            <div className="w-[90%] h-80 bg-gray-50">
                <div className="h-1/5 bg-lime-100 flex justify-start items-center">
                    <h1 className="font-medium text-3xl">Why choose us?</h1>
                </div>
                <div className="h-4/5 bg-orange-100 grid grid-cols-2 md:grid-cols-4 gap-4 p-4">
                    <div className="bg-white rounded-lg shadow-md p-4">Block 1</div>
                    <div className="bg-white rounded-lg shadow-md p-4">Block 2</div>
                    <div className="bg-white rounded-lg shadow-md p-4">Block 3</div>
                    <div className="bg-white rounded-lg shadow-md p-4">Block 4</div>
                </div>
            </div>
        </div>
    );
}

export default WhyUsSection;
